-- Tusan Website - Phase 2 service/form seed
-- Scope: vehicle + government/social-security + tax + insurance + university services.
-- Parent/child hierarchy and conditional rules remain intentionally excluded.
-- New services use price=0; existing prices are preserved.
-- Schemas use only field types currently supported by the Tusan form builder.

DO $$
DECLARE
  item jsonb;
  v_service_id uuid;
BEGIN
  FOR item IN SELECT value FROM jsonb_array_elements($services$
[
  {"title":"ثبت‌نام ایران‌خودرو","category":"خدمات خودرو","description":"ثبت اطلاعات متقاضی برای فرآیندهای فروش ایران‌خودرو.","icon":"🚗","fields":[{"id":"ikco_national_code","type":"national_code","label":"کد ملی","name":"national_code","required":true},{"id":"ikco_mobile","type":"phone","label":"شماره موبایل","name":"mobile","required":true},{"id":"ikco_birth_date","type":"date","label":"تاریخ تولد","name":"birth_date","required":true},{"id":"ikco_full_name","type":"text","label":"نام و نام خانوادگی","name":"full_name","required":true},{"id":"ikco_address","type":"textarea","label":"آدرس","name":"address","required":true},{"id":"ikco_postal_code","type":"text","label":"کد پستی","name":"postal_code","required":true},{"id":"ikco_vehicle","type":"text","label":"خودرو/محصول موردنظر","name":"vehicle","required":true}]},
  {"title":"ثبت‌نام سایپا","category":"خدمات خودرو","description":"ثبت اطلاعات متقاضی برای فرآیندهای فروش سایپا.","icon":"🚘","fields":[{"id":"saipa_national_code","type":"national_code","label":"کد ملی","name":"national_code","required":true},{"id":"saipa_mobile","type":"phone","label":"شماره موبایل","name":"mobile","required":true},{"id":"saipa_birth_date","type":"date","label":"تاریخ تولد","name":"birth_date","required":true},{"id":"saipa_full_name","type":"text","label":"نام و نام خانوادگی","name":"full_name","required":true},{"id":"saipa_address","type":"textarea","label":"آدرس","name":"address","required":true},{"id":"saipa_postal_code","type":"text","label":"کد پستی","name":"postal_code","required":true},{"id":"saipa_vehicle","type":"text","label":"خودرو/محصول موردنظر","name":"vehicle","required":true}]},
  {"title":"ثبت‌نام خودروهای وارداتی","category":"خدمات خودرو","description":"ثبت اطلاعات متقاضی برای فرآیندهای مربوط به خودروهای وارداتی.","icon":"🌐","fields":[{"id":"import_national_code","type":"national_code","label":"کد ملی","name":"national_code","required":true},{"id":"import_mobile","type":"phone","label":"شماره موبایل","name":"mobile","required":true},{"id":"import_birth_date","type":"date","label":"تاریخ تولد","name":"birth_date","required":true},{"id":"import_full_name","type":"text","label":"نام و نام خانوادگی","name":"full_name","required":true},{"id":"import_postal_code","type":"text","label":"کد پستی","name":"postal_code","required":true},{"id":"import_vehicle","type":"text","label":"خودرو/محصول موردنظر","name":"vehicle","required":true}]},
  {"title":"ثبت‌نام خودروهای برقی","category":"خدمات خودرو","description":"ثبت اطلاعات متقاضی برای طرح‌های فروش خودروهای برقی.","icon":"🔋","fields":[{"id":"ev_national_code","type":"national_code","label":"کد ملی","name":"national_code","required":true},{"id":"ev_mobile","type":"phone","label":"شماره موبایل","name":"mobile","required":true},{"id":"ev_birth_date","type":"date","label":"تاریخ تولد","name":"birth_date","required":true},{"id":"ev_full_name","type":"text","label":"نام و نام خانوادگی","name":"full_name","required":true},{"id":"ev_postal_code","type":"text","label":"کد پستی","name":"postal_code","required":true},{"id":"ev_vehicle","type":"text","label":"خودرو/محصول موردنظر","name":"vehicle","required":true}]},
