  {"title":"ثبت‌نام طرح فرسوده خودرو","category":"خدمات خودرو","description":"ثبت اطلاعات متقاضی طرح جایگزینی خودروهای فرسوده.","icon":"♻️","fields":[{"id":"scrap_national_code","type":"national_code","label":"کد ملی","name":"national_code","required":true},{"id":"scrap_mobile","type":"phone","label":"شماره موبایل","name":"mobile","required":true},{"id":"scrap_full_name","type":"text","label":"نام و نام خانوادگی","name":"full_name","required":true},{"id":"scrap_vehicle_type","type":"text","label":"نوع خودرو فرسوده","name":"vehicle_type","required":true},{"id":"scrap_plate","type":"text","label":"شماره پلاک","name":"plate","required":true},{"id":"scrap_vin","type":"text","label":"VIN در صورت وجود","name":"vin","required":false}]},
