  {"title":"ثبت‌نام تأمین اجتماعی","category":"خدمات تأمین اجتماعی","description":"ثبت درخواست ایجاد حساب و انجام خدمات اولیه تأمین اجتماعی.","icon":"🛡️","fields":[{"id":"ss_national_code","type":"national_code","label":"کد ملی","name":"national_code","required":true},{"id":"ss_full_name","type":"text","label":"نام و نام خانوادگی","name":"full_name","required":true},{"id":"ss_birth_date","type":"date","label":"تاریخ تولد","name":"birth_date","required":true},{"id":"ss_mobile","type":"phone","label":"شماره موبایل","name":"mobile","required":true},{"id":"ss_postal_code","type":"text","label":"کد پستی","name":"postal_code","required":true},{"id":"ss_address","type":"textarea","label":"آدرس","name":"address","required":true}]},
