  {"title":"ثبت‌نام در سامانه مالیاتی","category":"خدمات مالیاتی","description":"ثبت درخواست ایجاد یا تکمیل پرونده مالیاتی.","icon":"🧾","fields":[{"id":"tax_national_code","type":"national_code","label":"کد ملی/شناسه ملی","name":"national_or_entity_id","required":true},{"id":"tax_full_name","type":"text","label":"نام شخص/نام شرکت","name":"full_name","required":true},{"id":"tax_mobile","type":"phone","label":"شماره موبایل","name":"mobile","required":true},{"id":"tax_activity","type":"text","label":"نوع فعالیت","name":"activity","required":true},{"id":"tax_postal_code","type":"text","label":"کد پستی محل فعالیت","name":"postal_code","required":true},{"id":"tax_address","type":"textarea","label":"آدرس محل فعالیت","name":"address","required":true}]},
  {"title":"تشکیل پرونده مالیاتی","category":"خدمات مالیاتی","description":"ثبت اطلاعات لازم برای تشکیل پرونده مالیاتی.","icon":"📂","fields":[{"id":"case_id","type":"text","label":"کد ملی/شناسه ملی","name":"national_or_entity_id","required":true},{"id":"case_mobile","type":"phone","label":"شماره موبایل","name":"mobile","required":true},{"id":"case_activity","type":"text","label":"نوع فعالیت","name":"activity","required":true},{"id":"case_start_date","type":"date","label":"تاریخ شروع فعالیت","name":"activity_start_date","required":true},{"id":"case_postal_code","type":"text","label":"کد پستی","name":"postal_code","required":true},{"id":"case_address","type":"textarea","label":"آدرس","name":"address","required":true}]},
  {"title":"ثبت اظهارنامه مالیاتی","category":"خدمات مالیاتی","description":"ثبت درخواست تهیه و ارسال اظهارنامه؛ نوع اظهارنامه باید در زمان سفارش مشخص شود.","icon":"📊","fields":[{"id":"decl_id","type":"text","label":"کد ملی/شناسه ملی","name":"national_or_entity_id","required":true},{"id":"decl_mobile","type":"phone","label":"شماره موبایل","name":"mobile","required":true},{"id":"decl_type","type":"select","label":"نوع اظهارنامه","name":"declaration_type","required":true,"options":[{"label":"اشخاص حقیقی","value":"individual"},{"label":"اشخاص حقوقی","value":"legal"},{"label":"ارزش افزوده","value":"vat"}]},{"id":"decl_year","type":"number","label":"سال مالی","name":"financial_year","required":true},{"id":"decl_description","type":"textarea","label":"توضیحات","name":"description","required":false}]},
