  {"title":"تمدید بیمه خودرو","category":"خدمات بیمه","description":"ثبت درخواست تمدید بیمه خودرو.","icon":"🛡️","fields":[{"id":"renew_plate","type":"text","label":"شماره پلاک","name":"plate_number","required":true},{"id":"renew_national_code","type":"national_code","label":"کد ملی مالک","name":"national_code","required":true},{"id":"renew_mobile","type":"phone","label":"شماره موبایل","name":"mobile","required":true},{"id":"renew_insurance","type":"text","label":"شماره بیمه‌نامه قبلی در صورت وجود","name":"previous_policy_number","required":false}]},
  {"title":"ثبت‌نام دانشگاه آزاد","category":"خدمات آموزشی و دانشگاهی","description":"ثبت اطلاعات اولیه متقاضی برای فرآیند ثبت‌نام دانشگاه آزاد.","icon":"🎓","fields":[{"id":"iau_national_code","type":"national_code","label":"کد ملی","name":"national_code","required":true},{"id":"iau_full_name","type":"text","label":"نام و نام خانوادگی","name":"full_name","required":true},{"id":"iau_birth_date","type":"date","label":"تاریخ تولد","name":"birth_date","required":true},{"id":"iau_mobile","type":"phone","label":"شماره موبایل","name":"mobile","required":true},{"id":"iau_degree","type":"text","label":"مقطع تحصیلی","name":"degree","required":true},{"id":"iau_field","type":"text","label":"رشته تحصیلی","name":"field_of_study","required":true},{"id":"iau_gpa","type":"number","label":"معدل","name":"gpa","required":true},{"id":"iau_city","type":"text","label":"شهر محل سکونت","name":"city","required":true}]},
  {"title":"ثبت‌نام دانشگاه پیام نور","category":"خدمات آموزشی و دانشگاهی","description":"ثبت اطلاعات اولیه متقاضی برای فرآیند ثبت‌نام دانشگاه پیام نور.","icon":"🎓","fields":[{"id":"pnu_national_code","type":"national_code","label":"کد ملی","name":"national_code","required":true},{"id":"pnu_full_name","type":"text","label":"نام و نام خانوادگی","name":"full_name","required":true},{"id":"pnu_birth_date","type":"date","label":"تاریخ تولد","name":"birth_date","required":true},{"id":"pnu_mobile","type":"phone","label":"شماره موبایل","name":"mobile","required":true},{"id":"pnu_degree","type":"text","label":"مقطع تحصیلی","name":"degree","required":true},{"id":"pnu_field","type":"text","label":"رشته تحصیلی","name":"field_of_study","required":true}]},
  {"title":"ثبت‌نام دانشگاه علمی‌کاربردی","category":"خدمات آموزشی و دانشگاهی","description":"ثبت اطلاعات اولیه متقاضی برای فرآیند ثبت‌نام دانشگاه علمی‌کاربردی.","icon":"🎓","fields":[{"id":"uast_national_code","type":"national_code","label":"کد ملی","name":"national_code","required":true},{"id":"uast_full_name","type":"text","label":"نام و نام خانوادگی","name":"full_name","required":true},{"id":"uast_birth_date","type":"date","label":"تاریخ تولد","name":"birth_date","required":true},{"id":"uast_mobile","type":"phone","label":"شماره موبایل","name":"mobile","required":true},{"id":"uast_degree","type":"text","label":"مقطع تحصیلی","name":"degree","required":true},{"id":"uast_field","type":"text","label":"رشته تحصیلی","name":"field_of_study","required":true}]},
  {"title":"ثبت‌نام بدون کنکور","category":"خدمات آموزشی و دانشگاهی","description":"ثبت درخواست پذیرش بدون آزمون؛ دانشگاه و مقطع باید مشخص شود.","icon":"📚","fields":[{"id":"noc_exam_national_code","type":"national_code","label":"کد ملی","name":"national_code","required":true},{"id":"noc_exam_full_name","type":"text","label":"نام و نام خانوادگی","name":"full_name","required":true},{"id":"noc_exam_mobile","type":"phone","label":"شماره موبایل","name":"mobile","required":true},{"id":"noc_exam_university","type":"text","label":"دانشگاه موردنظر","name":"university","required":true},{"id":"noc_exam_degree","type":"text","label":"مقطع","name":"degree","required":true},{"id":"noc_exam_field","type":"text","label":"رشته موردنظر","name":"field_of_study","required":true},{"id":"noc_exam_gpa","type":"number","label":"معدل","name":"gpa","required":true}]},
  {"title":"ثبت درخواست نقل‌وانتقال دانشگاه","category":"خدمات آموزشی و دانشگاهی","description":"ثبت اطلاعات اولیه برای درخواست انتقال یا مهمانی دانشگاه.","icon":"🔄","fields":[{"id":"transfer_national_code","type":"national_code","label":"کد ملی","name":"national_code","required":true},{"id":"transfer_full_name","type":"text","label":"نام و نام خانوادگی","name":"full_name","required":true},{"id":"transfer_mobile","type":"phone","label":"شماره موبایل","name":"mobile","required":true},{"id":"transfer_current_university","type":"text","label":"دانشگاه مبدأ","name":"current_university","required":true},{"id":"transfer_target_university","type":"text","label":"دانشگاه مقصد","name":"target_university","required":true},{"id":"transfer_reason","type":"textarea","label":"دلیل درخواست","name":"reason","required":true}]},
  {"title":"درخواست وام دانشجویی","category":"خدمات دانشجویی","description":"ثبت اطلاعات اولیه برای درخواست تسهیلات دانشجویی.","icon":"💰","fields":[{"id":"loan_national_code","type":"national_code","label":"کد ملی","name":"national_code","required":true},{"id":"loan_full_name","type":"text","label":"نام و نام خانوادگی","name":"full_name","required":true},{"id":"loan_mobile","type":"phone","label":"شماره موبایل","name":"mobile","required":true},{"id":"loan_university","type":"text","label":"دانشگاه","name":"university","required":true},{"id":"loan_student_no","type":"text","label":"شماره دانشجویی","name":"student_number","required":true},{"id":"loan_type","type":"text","label":"نوع وام","name":"loan_type","required":true}]}
]$services$::jsonb) LOOP
    SELECT id INTO v_service_id FROM services WHERE title = item->>'title' LIMIT 1;
    IF v_service_id IS NULL THEN
      INSERT INTO services (title,category,description,price,icon,is_active,form_schema,parent_service_id)
      VALUES (item->>'title',item->>'category',item->>'description',0,item->>'icon',true,item->'fields',NULL)
      RETURNING id INTO v_service_id;
    ELSE
      UPDATE services SET category=item->>'category',description=item->>'description',icon=item->>'icon',is_active=true,form_schema=item->'fields' WHERE id=v_service_id;
    END IF;
    IF EXISTS (SELECT 1 FROM custom_forms WHERE service_id=v_service_id AND title=item->>'title') THEN
      UPDATE custom_forms SET description=item->>'description',schema=item->'fields',is_public=true,form_type='normal',parent_form_id=NULL WHERE service_id=v_service_id AND title=item->>'title';
    ELSE
      INSERT INTO custom_forms (title,description,schema,created_by,is_public,form_type,parent_form_id,service_id,sort_order)
      VALUES (item->>'title',item->>'description',item->'fields',NULL,true,'normal',NULL,v_service_id,0);
    END IF;
  END LOOP;
END $$;

-- Notes:
-- 1) طرح‌های خودرو، مالیاتی و دانشگاهی می‌توانند بر اساس دفترچه/بخشنامه دوره‌ای فیلدهای اختصاصی داشته باشند.
-- 2) فیلدهای شرطی عمداً در این seed فعال نشده‌اند و از Form Builder تنظیم خواهند شد.
-- 3) اطلاعات حساس مانند password, OTP و card credentials جمع‌آوری نمی‌شوند.
